css:
/* Hudson County Motors — site-wide design layer.
   Brand colours, fonts, type sizes and radii live in the design system (site/tokens.json).
   The handoff has a few more navy tones than the design system's eight colour slots;
   they are declared once here and used by name everywhere else. */
:root {
  --hcm-body: #41506A;        /* body copy (handoff --ink-600) */
  --hcm-placeholder: #7A8699; /* input placeholder (--ink-400) */
  --hcm-on-navy: #C4CEDC;     /* body copy on navy */
  --hcm-on-navy-2: #A7B4C8;   /* secondary on navy */
  --hcm-on-navy-3: #7A8FAD;   /* tertiary on dark navy */
  --hcm-nav-link: #E8EDF4;    /* nav links */
  --hcm-tint: #E4E9F0;        /* pre-owned badge, tints */
  --hcm-focus: #4D8EFF;
  --hcm-shadow: 0 8px 28px rgb(18 41 74 / 8%);
  --hcm-ease: cubic-bezier(.22, .61, .36, 1);
  --hcm-dur: 180ms;
  --hcm-section-gap: clamp(48px, 8vw, 80px);
  --hcm-grid-gap: 14px;
  --hcm-gutter: var(--container-pad);
}
@media (max-width: 1100px) { :root { --hcm-gutter: var(--container-pad-tablet); } }
@media (max-width: 640px) { :root { --hcm-gutter: var(--container-pad-mobile); } }

body { color: var(--hcm-body); overflow-x: hidden; }
a { transition: color var(--hcm-dur) var(--hcm-ease); }

/* Headings: Barlow Condensed, uppercase, navy. */
.bz-block :is(h1, h2, h3, h4) { font-family: var(--font-heading); font-weight: 700; text-transform: uppercase; color: var(--ink); letter-spacing: 0; }
.bz-block h1 { font-size: clamp(36px, 6vw, var(--text-h1)); line-height: 1; text-wrap: balance; margin: 0; }
.bz-block h2 { font-size: clamp(26px, 4vw, var(--text-h2)); line-height: 1.1; margin: 0 0 24px; }
.bz-block h3 { font-size: var(--text-h3); line-height: 1.1; }
.bz-block p { color: inherit; }

/* Eyebrow: a 26×4 tick and a tracked condensed label. */
.bz-eyebrow { display: flex; align-items: center; gap: 12px; margin: 0 0 18px; font: 600 clamp(13px, 1.6vw, var(--text-eyebrow))/1.2 var(--font-heading); letter-spacing: .22em; text-transform: uppercase; color: var(--muted); }
.bz-eyebrow::before { content: ""; width: 26px; height: 4px; background: var(--accent); flex: none; }

/* Buttons */
.bz-btns { gap: 16px; }
.bz-btn { font: 700 19px/1.2 var(--font-heading); letter-spacing: .06em; text-transform: uppercase; border-radius: var(--radius-input); padding: 16px 34px; border: 2px solid var(--accent); transition: background var(--hcm-dur) var(--hcm-ease), color var(--hcm-dur) var(--hcm-ease), border-color var(--hcm-dur) var(--hcm-ease), transform 120ms var(--hcm-ease); }
.bz-btn:active { transform: scale(.97); }
.bz-btn--primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.bz-btn--primary:hover { background: var(--accent-dark); border-color: var(--accent-dark); color: #fff; }
.bz-btn--secondary { background: transparent; border-color: var(--accent); color: var(--accent); padding: 14px 34px; }
.bz-btn--secondary:hover { background: var(--accent); border-color: var(--accent); color: #fff; }
.bz-btn--link { background: none; border: 0; border-bottom: 2px solid currentColor; border-radius: 0; padding: 0 0 2px; font-weight: 600; font-size: 17px; text-decoration: none; color: var(--accent); }
.bz-btn--link:hover { color: var(--accent-dark); }

/* Focus is always visible. */
a:focus-visible, button:focus-visible, .bz-block a:focus-visible, .bz-block button:focus-visible { outline: 2px solid var(--hcm-focus); outline-offset: 2px; }

/* Inputs */
.bz-input { background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius-input); color: var(--ink-dark); font: 15px var(--font-body); padding: 14px 16px; transition: border-color var(--hcm-dur), box-shadow var(--hcm-dur); }
.bz-input::placeholder { color: var(--hcm-placeholder); }
.bz-input:focus, .bz-input:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px rgb(24 71 134 / 15%); background: #fff; }

/* Cards: white, hairline, 6px; link cards lift and their photo eases in. */
.bz-card, .bz-quote { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius-card); overflow: hidden; }
a.bz-card { transition: box-shadow var(--hcm-dur) var(--hcm-ease), transform var(--hcm-dur) var(--hcm-ease); }
a.bz-card:hover { box-shadow: var(--hcm-shadow); transform: translateY(-3px); color: inherit; }
.bz-card img { transition: transform 380ms var(--hcm-ease); }
a.bz-card:hover img { transform: scale(1.04); }
@media (prefers-reduced-motion: reduce) { a.bz-card:hover, a.bz-card:hover img { transform: none; } }

/* Layout rhythm. The design spaces blocks with its own margins, and runs every band
   on one fluid gutter (the design system's container padding at each width). */
.bz-block, .bz-block + .bz-block { padding-block: 0; }
.bz-section > .bz-container { padding-inline: var(--hcm-gutter); }
@media (max-width: 640px) {
  .bz-section > .bz-container.bz-container--bleed-left,
  .bz-section > .bz-container.bz-container--bleed-right { padding-inline: var(--hcm-gutter); }
}

/* A photo column beside copy fills the column's height, whatever the photo's shape. */
[data-bz-node$="-media"] { position: relative; min-height: 260px; }
[data-bz-node$="-media"] > .bz-block--image, [data-bz-node$="-media"] .bz-figure { position: absolute; inset: 0; margin: 0; }
[data-bz-node$="-media"] .bz-container { height: 100%; }
[data-bz-node$="-media"] img { width: 100%; height: 100%; object-fit: cover; border-radius: 0; }

/* Logos and menu items size to their content, not to the body line-height. */
.bz-block--logo { display: flex; line-height: 0; }
.bz-navitem { line-height: 1.15; }

/* =====================================================================
   Inner pages — shared band pieces. The components under Components →
   Designed (content-split, content-stack, media-band, …) share these node ids,
   so one set of rules styles every band on every inner page.
   ===================================================================== */
:root {
  --hcm-navy: #102043;        /* body headings, strong copy */
  --hcm-on-blue: #DCE4EF;     /* body copy on the blue band */
  --hcm-pad-y: clamp(40px, 7vw, 72px);
  --hcm-col-gap: clamp(24px, 4vw, 56px);
}

/* Bands */
[data-bz-node="band"] { padding-block: var(--hcm-pad-y); }
[data-bz-node="band"].bz-section--bg-card { border-top: 1px solid var(--line); }
[data-bz-node="band"].bz-section--bg-accent { color: var(--hcm-on-blue); }
[data-bz-node="band"] > .bz-container > .bz-row + .bz-row { margin-top: 36px; }
[data-bz-node="band"] .bz-row:not(:has(> .bz-col)) { display: none; }
[data-bz-node="band"] > .bz-container > .bz-row:not(:has(:is(h1, h2, h3, p, a, img, iframe, form, details, .bz-map, .bz-widget))) { display: none; }
[data-bz-node="band"] .bz-block h2 { font-size: clamp(30px, 3.6vw, 42px); line-height: 1.05; margin: 0; }
[data-bz-node="band"] .bz-block--text p { font-size: 17px; line-height: 1.65; margin: 0 0 16px; }
[data-bz-node="band"] .bz-block--text p:last-child { margin-bottom: 0; }
[data-bz-node="band"] .bz-block--text a:not(.bz-btn) { color: var(--accent); font-weight: 600; text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
[data-bz-node="band"] .bz-block--text strong { color: var(--hcm-navy); }
[data-bz-node="band"] .bz-headingblock:empty, [data-bz-node="band"] .bz-block--heading:not(:has(:is(h1, h2, h3, h4):not(:empty))) { display: none; }
[data-bz-node="band"] .bz-block--image:has(.bz-photo--empty) { display: none; }

/* On the blue band */
.bz-section--bg-accent[data-bz-node="band"] .bz-block h2 { color: #fff; }
.bz-section--bg-accent[data-bz-node="band"] .bz-block--text p { color: var(--hcm-on-blue); }
.bz-section--bg-accent[data-bz-node="band"] .bz-block--text :is(a:not(.bz-btn), strong) { color: #fff; }
.bz-section--bg-accent[data-bz-node="band"] .bz-eyebrow { color: var(--hcm-on-navy-2); }
.bz-section--bg-accent[data-bz-node="band"] .bz-eyebrow::before { background: #fff; }
.bz-section--bg-accent .bz-btn--primary { background: #fff; border-color: #fff; color: var(--accent); }
.bz-section--bg-accent .bz-btn--primary:hover { background: var(--hcm-nav-link); border-color: var(--hcm-nav-link); color: var(--accent-dark); }

/* Heading group */
[data-bz-node="hcm-h"] .bz-eyebrow { margin-bottom: 14px; }
[data-bz-node="hcm-lead"] p { font: 700 16px/1.4 var(--font-body) !important; color: var(--accent) !important; }
.bz-section--bg-accent [data-bz-node="hcm-lead"] p { color: #fff !important; }

/* Split columns and paired paragraphs */
[data-bz-node="hcm-split"], [data-bz-node="hcm-bodyrow"], [data-bz-node="hcm-mediarow"], [data-bz-node="contact-row"], [data-bz-node="faq-row"], [data-bz-node="fg-row"], [data-bz-node="ctacard"] { gap: var(--hcm-col-gap); }
[data-bz-node="hcm-bodyrow"]:not(:has([data-bz-node="hcm-body2"] p)) > [data-bz-node="hcm-body-a"] { grid-column: 1 / -1; }
[data-bz-node="hcm-bodyrow"]:not(:has([data-bz-node="hcm-body2"] p)) > [data-bz-node="hcm-body-b"] { display: none; }
[data-bz-node="hcm-bodyrow"]:not(:has([data-bz-node="hcm-body2"] p)) [data-bz-node="hcm-body"] { max-width: 880px; }
@media (max-width: 900px) {
  :is([data-bz-node="hcm-split"], [data-bz-node="hcm-bodyrow"], [data-bz-node="hcm-mediarow"], [data-bz-node="contact-row"], [data-bz-node="faq-row"], [data-bz-node="ctacard"]) > .bz-col { grid-column: 1 / -1; }
}

/* Info card */
[data-bz-node="hcm-inforow"]:not(:has(:is(h3, p, a))) { display: none; }
[data-bz-node="hcm-info"] { background: var(--card); border: 1px solid var(--line); border-top: 3px solid var(--accent); border-radius: var(--radius-card); padding: clamp(22px, 3vw, 30px); display: flex; flex-direction: column; gap: 12px; color: var(--hcm-body); }
[data-bz-node="hcm-info"] > .bz-block { margin: 0; }
[data-bz-node="hcm-info-h"] h3 { font-size: 26px; line-height: 1.1; margin: 0; }
[data-bz-node="hcm-info-t"] p { font-size: 16px !important; color: var(--hcm-body) !important; }
[data-bz-node="hcm-info-t"] strong { color: var(--hcm-navy) !important; }
[data-bz-node="hcm-info-t"] a:not(.bz-btn) { color: var(--accent) !important; }
[data-bz-node="hcm-info-b"] .bz-btns { margin: 4px 0 0; gap: 10px; }
[data-bz-node="hcm-info-b"] .bz-btn { font-size: 16px; padding: 13px 24px; }

/* Link cards (callouts) */
[data-bz-node="hcm-callrow"] { gap: 16px; }
[data-bz-node^="hcmcall"] { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius-card); padding: 26px; display: flex; flex-direction: column; justify-content: space-between; gap: 18px; transition: box-shadow var(--hcm-dur) var(--hcm-ease); }
[data-bz-node^="hcmcall"]:hover { box-shadow: var(--hcm-shadow); }
[data-bz-node^="hcm-calltext"] p { font-weight: 500; color: var(--hcm-navy) !important; }
[data-bz-node^="hcm-callbtn"] .bz-btns { margin: 0; }
[data-bz-node^="hcm-callbtn"] .bz-btn { font-size: 16px; padding: 13px 24px; letter-spacing: .08em; background: var(--accent); border-color: var(--accent); color: #fff; }
[data-bz-node^="hcm-callbtn"] .bz-btn:hover { background: var(--accent-dark); border-color: var(--accent-dark); color: #fff; }
@media (max-width: 640px) { [data-bz-node^="hcmcall"] { grid-column: 1 / -1; } }

/* Cards: numbered feature cards, plain resource cards, and checklist items */
[data-bz-node="hcm-grid"] { gap: 16px; }
[data-bz-node^="hcmcard"] { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius-card); padding: 26px; display: flex; flex-direction: column; gap: 12px; color: var(--hcm-body); }
[data-bz-node^="hcmcard"] > .bz-block { margin: 0; }
[data-bz-node^="hcmcard"]:has([data-bz-node^="hcm-cardnum"] p) { border-top: 3px solid var(--accent); }
.bz-section--bg-accent [data-bz-node^="hcmcard"] { border: 0; }
[data-bz-node^="hcm-cardnum"] p { font: 700 15px/1.2 var(--font-heading) !important; letter-spacing: .14em; color: var(--muted) !important; margin: 0; }
[data-bz-node^="hcm-cardh"] h3 { font-size: 24px; line-height: 1.12; margin: 0; text-transform: none; }
[data-bz-node^="hcm-cardtext"] p { font-size: 16px !important; line-height: 1.65; color: var(--hcm-body) !important; }
.bz-section--bg-accent [data-bz-node^="hcm-cardtext"] p { color: var(--hcm-navy) !important; font-weight: 500; }
[data-bz-node^="hcm-cardtext"] strong { color: var(--hcm-navy); }
[data-bz-node^="hcmcard"]:not(:has(h3)):not(:has([data-bz-node^="hcm-cardnum"] p)),
[data-bz-node^="hcmcheck"] { flex-direction: row; align-items: center; gap: 14px; padding: 16px 18px; background: var(--paper); }
[data-bz-node^="hcmcard"]:not(:has(h3)):not(:has([data-bz-node^="hcm-cardnum"] p))::before,
[data-bz-node^="hcmcheck"]::before { content: "\2713"; flex: none; width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; border-radius: var(--radius-input); background: var(--accent); color: #fff; font: 700 16px/1 var(--font-body); }
[data-bz-node^="hcmcard"]:not(:has(h3)):not(:has([data-bz-node^="hcm-cardnum"] p)) [data-bz-node^="hcm-cardnum"] { display: none; }
[data-bz-node^="hcmcard"]:not(:has(h3)):not(:has([data-bz-node^="hcm-cardnum"] p)) [data-bz-node^="hcm-cardtext"] p,
[data-bz-node^="hcm-checktext"] p { font-weight: 600 !important; font-size: 16px !important; line-height: 1.4 !important; color: var(--hcm-navy) !important; }
[data-bz-node="hcm-checkrow"] { display: flex; flex-direction: column; gap: 12px; }
[data-bz-node="hcm-checkrow"] > .bz-col { width: 100%; }
@media (max-width: 1100px) { [data-bz-node^="hcmcard"][style*="--bz-span:3"], [data-bz-node^="hcmcard"][style*="--bz-span:4"] { grid-column: span 6; } }
@media (max-width: 640px) { [data-bz-node^="hcmcard"] { grid-column: 1 / -1 !important; } }

[data-bz-node^="hcm-cardlink"] { margin-top: auto !important; }
[data-bz-node^="hcm-cardlink"] .bz-btns { margin: 4px 0 0; }
[data-bz-node^="hcm-cardlink"] .bz-btn--link { border: 0; padding: 0; font-size: 16px; letter-spacing: .06em; }
[data-bz-node^="hcmcard"]:has([data-bz-node^="hcm-cardlink"] a) { background: var(--paper); transition: border-color var(--hcm-dur) var(--hcm-ease), box-shadow var(--hcm-dur) var(--hcm-ease); }
[data-bz-node^="hcmcard"]:has([data-bz-node^="hcm-cardlink"] a):hover { border-color: var(--accent); box-shadow: var(--hcm-shadow); }

/* Text after the cards, closing line + button */
[data-bz-node="hcm-after"] p, [data-bz-node="hcm-pre"] p { max-width: 880px; }
[data-bz-node="hcm-pre"] p { font-weight: 600; color: var(--hcm-navy); }
.bz-section--bg-accent [data-bz-node="hcm-pre"] p { color: #fff; }
[data-bz-node="band"] > .bz-container > [data-bz-node="hcm-prerow"] + [data-bz-node="hcm-grid"] { margin-top: 20px; }
[data-bz-node="hcm-foot"] { display: flex; flex-wrap: wrap; align-items: center; gap: 18px; }
[data-bz-node="hcm-foot"] > .bz-col { flex: 0 1 auto; }
[data-bz-node="hcm-foot"]:has([data-bz-node="hcm-note"] p) { justify-content: space-between; border-top: 1px solid var(--line); padding-top: 20px; }
.bz-section--bg-accent [data-bz-node="hcm-foot"]:has([data-bz-node="hcm-note"] p) { border-top-color: rgb(255 255 255 / 20%); }
[data-bz-node="hcm-foot-n"]:not(:has(p)), [data-bz-node="hcm-foot-c"]:not(:has(a)) { display: none; }
[data-bz-node="hcm-foot"] > [data-bz-node="hcm-foot-n"] { flex: 1 1 420px; }
[data-bz-node="hcm-note"] p { font-weight: 500; color: var(--hcm-navy) !important; }
.bz-section--bg-accent [data-bz-node="hcm-note"] p { color: #fff !important; }
[data-bz-node="hcm-cta"] .bz-btns { margin: 0; }
[data-bz-node="hcm-text"] [data-bz-node="hcm-foot"] { margin-top: 8px; }

/* Aside image (a logo or rate sheet shown whole, on a white card) */
[data-bz-node="hcm-aside-img"] .bz-figure { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius-card); padding: 18px; }
[data-bz-node="hcm-aside-img"] img { margin-inline: auto; border-radius: var(--radius-input); }

/* Forms (library forms placed on pages) */
.bz-form .bz-label { font: 600 14px/1.35 var(--font-body); color: var(--hcm-navy); }
.bz-form .bz-req { font-size: 0; }
.bz-form .bz-req::after { content: "(Required)"; font: 600 12px/1 var(--font-body); color: #B42318; margin-left: 2px; }
.bz-form .bz-choice { font-size: 15px; color: var(--hcm-body); }
.bz-form .bz-btn[type="submit"] { align-self: flex-start; flex: 0 0 auto; }
[data-bz-node="cf-form"] .bz-form, [data-bz-node="finance-form"] .bz-form { max-width: none; }
[data-bz-node="cf-form"] .bz-form__t, [data-bz-node="finance-form"] .bz-form__t { display: none; }
